package youtubemusic

import (
	"fmt"
	"strings"
)

// autoGenerated builds a videos.list item for an auto-generated track.
func autoGenerated(videoID, title string, artists ...string) string {
	return fmt.Sprintf(`{"id":%q,"snippet":{"title":%q,"channelTitle":%q,"description":%q}}`,
		videoID, title, artists[0]+" - Topic",
		"Provided to YouTube by Label\n\n"+title+" · "+strings.Join(artists, " · ")+"\n\nAlbum\n\nReleased on: 2020-05-01\n\nAuto-generated by YouTube.")
}
